#!/bin/bash\n\n# Air-Gapped RAG Deployment Script\n# Automates the complete deployment process\n\nset -euo pipefail\n\n# Configuration\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nPROJECT_ROOT=\"$(dirname \"$SCRIPT_DIR\")\"\nLOG_FILE=\"/tmp/rag-deploy-$(date +%Y%m%d-%H%M%S).log\"\nENVIRONMENT=\"${1:-dev}\"\nACTION=\"${2:-deploy}\"\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# Logging functions\nlog() {\n    echo -e \"[$(date '+%Y-%m-%d %H:%M:%S')] $*\" | tee -a \"$LOG_FILE\"\n}\n\nlog_info() {\n    log \"${BLUE}[INFO]${NC} $*\"\n}\n\nlog_warn() {\n    log \"${YELLOW}[WARN]${NC} $*\"\n}\n\nlog_error() {\n    log \"${RED}[ERROR]${NC} $*\"\n}\n\nlog_success() {\n    log \"${GREEN}[SUCCESS]${NC} $*\"\n}\n\n# Error handling\nerror_exit() {\n    log_error \"$1\"\n    log_error \"Deployment failed. Check log file: $LOG_FILE\"\n    exit 1\n}\n\n# Cleanup function\ncleanup() {\n    log_info \"Cleaning up temporary files...\"\n    # Add cleanup logic here if needed\n}\n\n# Set trap for cleanup\ntrap cleanup EXIT\n\n# Usage function\nusage() {\n    cat << EOF\nUsage: $0 [ENVIRONMENT] [ACTION]\n\nENVIRONMENT:\n    dev      - Development environment (default)\n    staging  - Staging environment\n    prod     - Production environment\n\nACTION:\n    deploy   - Deploy infrastructure and configure services (default)\n    destroy  - Destroy infrastructure\n    update   - Update existing deployment\n    status   - Check deployment status\n\nExamples:\n    $0 dev deploy     # Deploy to development\n    $0 prod update    # Update production\n    $0 staging status # Check staging status\n\nEOF\n}\n\n# Validate environment\nvalidate_environment() {\n    log_info \"Validating environment: $ENVIRONMENT\"\n    \n    if [[ ! \"$ENVIRONMENT\" =~ ^(dev|staging|prod)$ ]]; then\n        error_exit \"Invalid environment: $ENVIRONMENT. Must be dev, staging, or prod.\"\n    fi\n    \n    # Check if config file exists\n    local config_file=\"$PROJECT_ROOT/config/${ENVIRONMENT}.env\"\n    if [[ ! -f \"$config_file\" ]]; then\n        error_exit \"Configuration file not found: $config_file\"\n    fi\n    \n    # Load configuration\n    source \"$config_file\"\n    \n    # Validate required variables\n    local required_vars=(\"AWS_REGION\" \"AWS_ACCOUNT_ID\" \"HOME_IP\" \"VPC_CIDR\")\n    for var in \"${required_vars[@]}\"; do\n        if [[ -z \"${!var:-}\" ]]; then\n            error_exit \"Required variable $var is not set in $config_file\"\n        fi\n    done\n    \n    log_success \"Environment validation passed\"\n}\n\n# Check prerequisites\ncheck_prerequisites() {\n    log_info \"Checking prerequisites...\"\n    \n    # Check required tools\n    local required_tools=(\"aws\" \"cdk\" \"python3\" \"uv\")\n    for tool in \"${required_tools[@]}\"; do\n        if ! command -v \"$tool\" &> /dev/null; then\n            error_exit \"Required tool not found: $tool\"\n        fi\n    done\n    \n    # Check AWS credentials\n    if ! aws sts get-caller-identity &> /dev/null; then\n        error_exit \"AWS credentials not configured or invalid\"\n    fi\n    \n    # Check CDK bootstrap\n    local account_id=$(aws sts get-caller-identity --query Account --output text)\n    local region=$(aws configure get region || echo \"us-east-1\")\n    \n    if ! aws cloudformation describe-stacks --stack-name CDKToolkit --region \"$region\" &> /dev/null; then\n        log_warn \"CDK not bootstrapped. Running bootstrap...\"\n        cdk bootstrap \"aws://${account_id}/${region}\" || error_exit \"CDK bootstrap failed\"\n    fi\n    \n    log_success \"Prerequisites check passed\"\n}\n\n# Install dependencies\ninstall_dependencies() {\n    log_info \"Installing dependencies...\"\n    \n    cd \"$PROJECT_ROOT\"\n    \n    # Install Python dependencies\n    if [[ ! -d \".venv\" ]]; then\n        log_info \"Creating virtual environment...\"\n        uv venv\n    fi\n    \n    log_info \"Installing Python packages...\"\n    uv sync --extra dev\n    \n    log_success \"Dependencies installed\"\n}\n\n# Deploy infrastructure\ndeploy_infrastructure() {\n    log_info \"Deploying infrastructure for $ENVIRONMENT...\"\n    \n    cd \"$PROJECT_ROOT\"\n    \n    # Activate virtual environment\n    source .venv/bin/activate\n    \n    # Deploy CDK stack\n    local stack_name=\"AirGappedRag-${ENVIRONMENT^}\"\n    \n    case \"$ACTION\" in\n        \"deploy\")\n            cdk deploy \"$stack_name\" --require-approval never --outputs-file \"cdk-outputs-${ENVIRONMENT}.json\"\n            ;;\n        \"update\")\n            cdk deploy \"$stack_name\" --require-approval never --outputs-file \"cdk-outputs-${ENVIRONMENT}.json\"\n            ;;\n        \"destroy\")\n            cdk destroy \"$stack_name\" --force\n            return 0\n            ;;\n        \"status\")\n            aws cloudformation describe-stacks --stack-name \"$stack_name\" --query 'Stacks[0].StackStatus' --output text\n            return 0\n            ;;\n    esac\n    \n    log_success \"Infrastructure deployment completed\"\n}\n\n# Configure VPN\nconfigure_vpn() {\n    log_info \"Configuring VPN connection...\"\n    \n    # Check if VPN setup script exists\n    local vpn_script=\"$PROJECT_ROOT/scripts/setup_vpn.sh\"\n    if [[ ! -f \"$vpn_script\" ]]; then\n        log_warn \"VPN setup script not found: $vpn_script\"\n        return 0\n    fi\n    \n    # Run VPN setup (requires root)\n    if [[ $EUID -eq 0 ]]; then\n        bash \"$vpn_script\" \"$ENVIRONMENT\"\n    else\n        log_warn \"VPN configuration requires root privileges. Run manually:\"\n        log_warn \"sudo $vpn_script $ENVIRONMENT\"\n    fi\n    \n    log_success \"VPN configuration completed\"\n}\n\n# Deploy worker service\ndeploy_worker() {\n    log_info \"Deploying worker service...\"\n    \n    # Create service user if it doesn't exist\n    if ! id \"rag-worker\" &>/dev/null; then\n        if [[ $EUID -eq 0 ]]; then\n            useradd -r -s /bin/false -d /opt/ai-inference rag-worker\n        else\n            log_warn \"Creating service user requires root privileges\"\n        fi\n    fi\n    \n    # Install systemd service files\n    local service_files=(\"rag-worker.service\" \"rag-monitor.service\")\n    for service_file in \"${service_files[@]}\"; do\n        local src=\"$PROJECT_ROOT/systemd/$service_file\"\n        local dst=\"/etc/systemd/system/$service_file\"\n        \n        if [[ -f \"$src\" ]]; then\n            if [[ $EUID -eq 0 ]]; then\n                cp \"$src\" \"$dst\"\n                systemctl daemon-reload\n                systemctl enable \"$service_file\"\n            else\n                log_warn \"Installing systemd services requires root privileges\"\n                log_warn \"Run manually: sudo cp $src $dst && sudo systemctl enable $service_file\"\n            fi\n        fi\n    done\n    \n    log_success \"Worker service deployment completed\"\n}\n\n# Validate deployment\nvalidate_deployment() {\n    log_info \"Validating deployment...\"\n    \n    # Check if CDK outputs file exists\n    local outputs_file=\"$PROJECT_ROOT/cdk-outputs-${ENVIRONMENT}.json\"\n    if [[ ! -f \"$outputs_file\" ]]; then\n        log_warn \"CDK outputs file not found: $outputs_file\"\n        return 0\n    fi\n    \n    # Extract key outputs\n    local queue_url=$(jq -r \".\\\"AirGappedRag-${ENVIRONMENT^}\\\".QueueUrl\" \"$outputs_file\" 2>/dev/null || echo \"\")\n    local log_group=$(jq -r \".\\\"AirGappedRag-${ENVIRONMENT^}\\\".LogGroupName\" \"$outputs_file\" 2>/dev/null || echo \"\")\n    \n    if [[ -n \"$queue_url\" && \"$queue_url\" != \"null\" ]]; then\n        log_success \"SQS Queue deployed: $queue_url\"\n    else\n        log_warn \"Could not validate SQS queue deployment\"\n    fi\n    \n    if [[ -n \"$log_group\" && \"$log_group\" != \"null\" ]]; then\n        log_success \"CloudWatch Log Group deployed: $log_group\"\n    else\n        log_warn \"Could not validate CloudWatch log group deployment\"\n    fi\n    \n    # Test AWS connectivity\n    if aws sts get-caller-identity &> /dev/null; then\n        log_success \"AWS connectivity validated\"\n    else\n        log_warn \"AWS connectivity test failed\"\n    fi\n    \n    log_success \"Deployment validation completed\"\n}\n\n# Print deployment summary\nprint_summary() {\n    log_info \"Deployment Summary\"\n    log_info \"==================\"\n    log_info \"Environment: $ENVIRONMENT\"\n    log_info \"Action: $ACTION\"\n    log_info \"Log file: $LOG_FILE\"\n    \n    if [[ -f \"$PROJECT_ROOT/cdk-outputs-${ENVIRONMENT}.json\" ]]; then\n        log_info \"CDK Outputs:\"\n        cat \"$PROJECT_ROOT/cdk-outputs-${ENVIRONMENT}.json\" | jq . 2>/dev/null || cat \"$PROJECT_ROOT/cdk-outputs-${ENVIRONMENT}.json\"\n    fi\n    \n    log_info \"Next Steps:\"\n    log_info \"1. Configure VPN connection (if not done automatically)\"\n    log_info \"2. Start worker service: sudo systemctl start rag-worker\"\n    log_info \"3. Monitor logs: sudo journalctl -u rag-worker -f\"\n    log_info \"4. Test with dashboard: streamlit run dashboard.py\"\n}\n\n# Main execution\nmain() {\n    log_info \"Starting Air-Gapped RAG deployment\"\n    log_info \"Environment: $ENVIRONMENT, Action: $ACTION\"\n    \n    # Show usage if help requested\n    if [[ \"$1\" == \"-h\" || \"$1\" == \"--help\" ]]; then\n        usage\n        exit 0\n    fi\n    \n    validate_environment\n    check_prerequisites\n    \n    case \"$ACTION\" in\n        \"deploy\"|\"update\")\n            install_dependencies\n            deploy_infrastructure\n            configure_vpn\n            deploy_worker\n            validate_deployment\n            print_summary\n            ;;\n        \"destroy\")\n            deploy_infrastructure  # This will destroy\n            log_success \"Infrastructure destroyed\"\n            ;;\n        \"status\")\n            deploy_infrastructure  # This will show status\n            ;;\n        *)\n            error_exit \"Invalid action: $ACTION. Use deploy, update, destroy, or status.\"\n            ;;\n    esac\n    \n    log_success \"Deployment completed successfully!\"\n}\n\n# Run main function with all arguments\nmain \"$@\"